function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;['transactions','accounts','members','budgets','reminders','categories','farm','groceryLists','orders'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id'})});if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta',{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function store(name,mode='readonly'){return db.transaction(name,mode).objectStore(name)}function all(name){return new Promise((res,rej)=>{let r=store(name).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}function put(name,obj){return new Promise((res,rej)=>{let tx=db.transaction(name,'readwrite');tx.objectStore(name).put(obj);tx.oncomplete=()=>res(obj);tx.onerror=()=>rej(tx.error)})}function del(name,id){return new Promise((res,rej)=>{let tx=db.transaction(name,'readwrite');tx.objectStore(name).delete(id);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}function clearStore(name){return new Promise((res,rej)=>{let tx=db.transaction(name,'readwrite');tx.objectStore(name).clear();tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}function today(){return new Date().toISOString().slice(0,10)}function currentMonth(){return today().slice(0,7)}function fmt(n,c='INR'){try{return new Intl.NumberFormat(state.lang==='hi'?'hi-IN':'en-IN',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(n)||0)}catch{return c+' '+(Number(n)||0).toFixed(2)}}function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
async function seed(){const a=await all('accounts');if(!a.length)await put('accounts',{id:uid(),name:state.lang==='hi'?'कैश':'Cash',type:'cash',currency:'INR',opening:0,createdAt:new Date().toISOString()});}
function setLang(lang){state.lang=lang;localStorage.setItem('hem_lang',lang);document.documentElement.lang=lang==='hi'?'hi':'en';$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(dict[lang][k])el.textContent=dict[lang][k]});$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=tr(el.dataset.i18nPlaceholder));$('#langToggle').textContent=lang==='hi'?'English':'हिंदी';$('#todayLabel').textContent=new Intl.DateTimeFormat(lang==='hi'?'hi-IN':'en-IN',{dateStyle:'full'}).format(new Date());renderAll();if(typeof renderDashboardCategoryGrid==='function')renderDashboardCategoryGrid();translateGrocery()}
function go(page){$$('.page').forEach(p=>p.classList.toggle('active',p.id===page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'});if(page==='reports')renderReports()}
function opt(value,label,selected=false){return `<option value="${escapeHtml(value)}" ${selected?'selected':''}>${escapeHtml(label)}</option>`}
function field(name,label,type='text',value='',opts={},full=false){let html='';if(type==='select'&&name==='category'&&state.modalExtra?.category){html=`<input name="${name}" type="text" value="${escapeHtml(value??'')}" readonly class="category-selected-value">`}else if(type==='select'&&name==='category'){const selected=String(value??'');const icons=[['shared household','🏠'],['groceries','🛒'],['utilities','💡'],['rent','🏡'],['education','🎓'],['health','🩺'],['travel','🚗'],['maintenance','🔧'],['pocket money','👛'],['miscellaneous','🧾'],['e-commerce','📦'],['shopping','🛍️'],['personal','👤'],['farming','🌱'],['livestock','🐄'],['loan','🤝'],['insurance','🛡️'],['savings','📈'],['subscriptions','🔔'],['food','🍽️'],['gifts','🎁']];const emojiFor=t=>{const x=String(t||'').toLowerCase();const hit=icons.find(([k])=>x.includes(k));if(hit)return hit[1];if(x.includes('किराना'))return '🛒';if(x.includes('बिजली')||x.includes('utility')||x.includes('bill'))return '💡';if(x.includes('शिक्षा')||x.includes('education'))return '🎓';if(x.includes('स्वास्थ्य')||x.includes('medicine')||x.includes('health'))return '🩺';if(x.includes('खेती')||x.includes('farm'))return '🌱';if(x.includes('बीमा')||x.includes('insurance'))return '🛡️';if(x.includes('उधार')||x.includes('loan'))return '🤝';if(x.includes('rent')||x.includes('किराया'))return '🏡';return '📁'};html=`<select class="category-native-select" name="${name}" ${opts.required?'required':''}>${opts.options.map(o=>opt(o.value,o.label,o.value===value)).join('')}</select><div class="category-icon-grid">${opts.options.map(o=>`<button type="button" class="category-icon-option ${String(o.value)===selected?'selected':''}" data-category-value="${escapeHtml(o.value)}"><span class="category-icon-emoji">${emojiFor(o.label)}</span><span class="category-icon-label">${escapeHtml(o.label)}</span></button>`).join('')}</div>`}else if(type==='select'){html=`<select name="${name}" ${opts.required?'required':''}>${opts.options.map(o=>opt(o.value,o.label,o.value===value)).join('')}</select>`}else if(type==='textarea'){html=`<textarea name="${name}" placeholder="${escapeHtml(opts.placeholder||'')}">${escapeHtml(value||'')}</textarea>`}else{html=`<input name="${name}" type="${type}" value="${escapeHtml(value??'')}" ${opts.required?'required':''} ${opts.step?`step="${opts.step}"`:''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.placeholder?`placeholder="${escapeHtml(opts.placeholder)}"`:''}>`}return `<div class="field ${full?'full':''}"><label>${escapeHtml(label)}</label>${html}</div>`}
function selectOpts(arr,selected){return arr.map(x=>({value:x.value,label:x.label}));}function categoryOptions(type){let keys=baseCategories.filter(k=>type==='income'?['salary','business','farmIncomeCat','milkIncome','rentIncome','interest','otherIncome'].includes(k):type==='expense'? !['salary','business','farmIncomeCat','milkIncome','rentIncome','interest','otherIncome'].includes(k):true);return keys.map(k=>({value:tr(k),label:tr(k)})).concat((window.customCategories||[]).map(c=>({value:c.name,label:c.name})));}
function openModal(kind,existing=null,extra=null){state.modalKind=kind;state.editing=existing;state.modalExtra=extra;const fields=$('#modalFields');let html='',title='';const accounts=window.accounts||[],members=window.members||[],accountOpts=accounts.map(a=>({value:a.id,label:a.name+' · '+a.currency})),memberOpts=[{value:'',label:tr('none')},...members.map(m=>({value:m.id,label:m.name}))];const currencyOpts=currencies.map(c=>({value:c,label:c}));const methodOpts=['cashMethod','upiMethod','bankTransfer','debitCard','creditCard','cheque','otherMethod'].map(k=>({value:tr(k),label:tr(k)}));const base=existing||{};
if(kind==='transaction'||kind==='farmTransaction'){title=existing?tr('edit')+' '+tr('transactions'):kind==='farmTransaction'?tr('addFarmRecord'):tr('addEntry');let type=extra?.type||base.type||'expense';html+=field('type',tr('type'),'select',type,{required:true,options:[{value:'expense',label:tr('expenseType')},{value:'income',label:tr('incomeType')},{value:'transfer',label:tr('transferType')},{value:'loan-given',label:tr('loanGivenType')},{value:'loan-taken',label:tr('loanTakenType')},{value:'repayment',label:tr('repaymentType')}]});html+=field('date',tr('date'),'date',base.date||today(),{required:true});html+=field('amount',tr('amount'),'number',base.amount??'',{required:true,min:'0.01',step:'0.01'});html+=field('currency',tr('currency'),'select',base.currency||'INR',{required:true,options:currencyOpts});const chosenCategory=extra?.category||base.category||tr(type==='income'?'salary':kind==='farmTransaction'?'farmingCategory':'groceries');const chosenSubcategory=extra?.subcategory||base.subcategory||'';const subOptions=subcategoryOptions(chosenCategory);if(chosenSubcategory&&!subOptions.some(o=>o.value===chosenSubcategory))subOptions.push({value:chosenSubcategory,label:chosenSubcategory});html+=field('category',tr('category'),'select',chosenCategory,{options:categoryOptions(type)});html+=field('subcategory',tr('subcategory'),'select',chosenSubcategory,{options:subOptions});html+=field('reason',tr('reason'),'textarea',base.reason||base.notes||'',{},true);if(type==='transfer'){html+=field('fromAccount',tr('fromAccount'),'select',base.fromAccount||accounts[0]?.id,{required:true,options:accountOpts});html+=field('toAccount',tr('toAccount'),'select',base.toAccount||accounts[1]?.id||accounts[0]?.id,{required:true,options:accountOpts})}else{html+=field('account',tr('account'),'select',base.account||accounts[0]?.id,{required:true,options:accountOpts});}html+=field('member',tr('member'),'select',base.member||'',{options:memberOpts});html+=field('method',tr('method'),'select',base.method||tr('cashMethod'),{options:methodOpts});html+=field('person',tr('person'),'text',base.person||'',{placeholder:tr('person')});html+=field('title',tr('title'),'text',base.title||'',{placeholder:tr('title')});if(kind==='farmTransaction'||type==='expense'&&base.farm){html+=field('crop',tr('crop'),'text',base.crop||'');html+=field('workType',tr('workType'),'select',base.workType||'fieldWork',{options:['fieldWork','ploughing','sowing','irrigation','fertilizer','harvest','machinery','animalCare','cropSale','milkSale'].map(k=>({value:k,label:tr(k)}))})}html+=field('notes',tr('notes'),'textarea',base.notes||'',{},true);}
else if(kind==='mobileRecharge'){title=state.lang==='hi'?'मोबाइल रिचार्ज दर्ज करें':'Add mobile recharge';html+=field('date',tr('date'),'date',base.date||today(),{required:true});html+=field('person',state.lang==='hi'?'किसका रिचार्ज?':'Recharge for', 'text',base.person||'',{required:true,placeholder:state.lang==='hi'?'नाम':'Family member name'});html+=field('phone',state.lang==='hi'?'मोबाइल नंबर':'Mobile number','tel',base.phone||'',{required:true,placeholder:'10 digit mobile number'});html+=field('operator',state.lang==='hi'?'ऑपरेटर':'Operator','select',base.operator||'Jio',{options:['Jio','Airtel','Vi','BSNL','Other'].map(x=>({value:x,label:x}))});html+=field('plan',state.lang==='hi'?'प्लान / अवधि':'Plan / validity','select',base.plan||'28 days',{options:[{value:'28 days',label:state.lang==='hi'?'28 दिन':'28 days'},{value:'56 days',label:state.lang==='hi'?'56 दिन':'56 days'},{value:'84 days',label:state.lang==='hi'?'84 दिन':'84 days'},{value:'365 days',label:state.lang==='hi'?'365 दिन':'365 days'},{value:'Other',label:state.lang==='hi'?'अन्य':'Other'}]});html+=field('amount',tr('amount'),'number',base.amount||'',{required:true,min:'1',step:'0.01'});html+=field('currency',tr('currency'),'select',base.currency||'INR',{required:true,options:currencyOpts});html+=field('expiryDate',state.lang==='hi'?'प्लान समाप्ति तारीख':'Plan expiry date', 'date',base.expiryDate||'',{required:true});html+=field('reminderDays',state.lang==='hi'?'रिमाइंडर':'Remind before expiry','select',base.reminderDays||'3,1,0',{options:[{value:'3,1,0',label:state.lang==='hi'?'3 दिन, 1 दिन और उसी दिन':'3 days, 1 day and on expiry'},{value:'1,0',label:state.lang==='hi'?'1 दिन पहले और उसी दिन':'1 day and on expiry'},{value:'0',label:state.lang==='hi'?'केवल समाप्ति वाले दिन':'On expiry only'}]});html+=field('method',tr('method'),'select',base.method||tr('upiMethod'),{options:methodOpts});html+=field('notes',tr('notes'),'textarea',base.notes||'',{},true);}
else if(kind==='account'){title=existing?tr('edit')+' '+tr('accounts'):tr('addAccount');html+=field('name',tr('name'),'text',base.name||'',{required:true});html+=field('type',tr('accountType'),'select',base.type||'cash',{options:[{value:'cash',label:tr('cash')},{value:'bank',label:tr('bank')},{value:'upi',label:tr('upi')},{value:'card',label:tr('card')},{value:'wallet',label:tr('wallet')},{value:'other',label:tr('other')}]});html+=field('currency',tr('currency'),'select',base.currency||'INR',{options:currencyOpts});html+=field('opening',tr('openingBalance'),'number',base.opening??0,{step:'0.01'});}
else if(kind==='member'){title=existing?tr('edit'):tr('addMember');html+=field('name',tr('memberName'),'text',base.name||'',{required:true});html+=field('phone',tr('phone'),'text',base.phone||'');}
else if(kind==='budget'){title=tr('setBudget');html+=field('category',tr('category'),'select',base.category||tr('groceries'),{options:categoryOptions('expense')});html+=field('amount',tr('budgetAmount'),'number',base.amount||'',{required:true,min:'1',step:'0.01'});}
else if(kind==='reminder'){title=tr('addReminder');html+=field('title',tr('reminderTitle'),'text',base.title||'',{required:true});html+=field('dueDate',tr('dueDate'),'date',base.dueDate||today(),{required:true});html+=field('amount',tr('amount'),'number',base.amount||'',{step:'0.01',min:'0'});html+=field('frequency',tr('frequency'),'select',base.frequency||'once',{options:[{value:'once',label:tr('once')},{value:'monthly',label:tr('monthly')},{value:'yearly',label:tr('yearly')}]});html+=field('status',tr('status'),'select',base.status||'due',{options:[{value:'due',label:tr('due')},{value:'paid',label:tr('paid')}]});html+=field('notes',tr('notes'),'textarea',base.notes||'',{},true);}
else if(kind==='category'){title=tr('addCategory');html+=field('name',tr('categoryName'),'text',base.name||'',{required:true});}
$('#modalTitle').textContent=title;fields.innerHTML=html;$('#modalRoot').hidden=false;$('#modalRoot').dataset.kind=kind;$('#modalRoot').dataset.editId=existing?.id||'';$('#modalForm').onsubmit=submitModal;const cat=$('#modalFields select[name=category]');if(cat){cat.addEventListener('change',()=>{const sub=$('#modalFields select[name=subcategory]');if(sub)sub.innerHTML=subcategoryOptions(cat.value).map(o=>opt(o.value,o.label,o.value===sub.value)).join('');$$('#modalFields .category-icon-option').forEach(b=>b.classList.toggle('selected',b.dataset.categoryValue===cat.value))});$$('#modalFields .category-icon-option').forEach(b=>b.addEventListener('click',()=>{cat.value=b.dataset.categoryValue;cat.dispatchEvent(new Event('change',{bubbles:true}))}));}}
function closeModal(){$('#modalRoot').hidden=true;$('#modalForm').onsubmit=null}
async function submitModal(e){e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f.entries()),kind=state.modalKind,existing=state.editing;const id=existing?.id||uid();if(kind==='transaction'||kind==='farmTransaction'){o.amount=Number(o.amount);if(!(o.amount>0)){toast(tr('amountPositive'));return}if(o.type==='transfer'&&o.fromAccount===o.toAccount){toast(tr('sameAccount'));return}o.id=id;o.notes=o.reason||o.notes||'';o.farm=kind==='farmTransaction'||!!o.crop||!!o.workType;o.createdAt=existing?.createdAt||new Date().toISOString();o.updatedAt=new Date().toISOString();await put('transactions',o);if(o.farm)await put('farm',{id:o.id,transactionId:o.id,date:o.date,amount:o.amount,currency:o.currency,type:o.type,category:o.category,crop:o.crop||'',workType:o.workType||'',title:o.title||o.category,notes:o.notes||''});}
else if(kind==='mobileRecharge'){o.id=id;o.type='expense';o.category=state.modalExtra?.category||tr('utilities');o.subcategory=state.modalExtra?.subcategory||(state.lang==='hi'?'मोबाइल रिचार्ज':'Mobile recharge');o.title=(state.lang==='hi'?'रिचार्ज — ':'Recharge — ')+o.person;o.amount=Number(o.amount)||0;o.currency=o.currency||'INR';o.account=(window.accounts||[])[0]?.id||'';o.member='';o.reason=o.notes||'';o.createdAt=existing?.createdAt||new Date().toISOString();o.updatedAt=new Date().toISOString();if(!(o.amount>0)){toast(tr('amountPositive'));return}await put('transactions',o);const days=String(o.reminderDays||'3,1,0').split(',').map(Number);for(const d of days){const date=new Date(o.expiryDate+'T12:00:00');date.setDate(date.getDate()-d);const dueDate=date.toISOString().slice(0,10);const rid='recharge-'+o.id+'-'+d;await put('reminders',{id:rid,title:(state.lang==='hi'?'रिचार्ज रिमाइंडर: ':'Recharge reminder: ')+o.person+' ('+o.phone+')',dueDate,amount:o.amount,frequency:'once',status:'due',notes:(o.operator||'')+' · '+(o.plan||'')+' · expiry '+o.expiryDate,kind:'mobileRecharge',transactionId:o.id,phone:o.phone,person:o.person});}if('Notification'in window&&Notification.permission==='default'){Notification.requestPermission().catch(()=>{});}if('Notification'in window&&Notification.permission==='granted'&&days.some(d=>{const x=new Date(o.expiryDate+'T12:00:00');x.setDate(x.getDate()-d);return x.toISOString().slice(0,10)===today()})){try{new Notification('GharKhata: Mobile recharge reminder',{body:o.person+' · '+o.phone+' · '+o.expiryDate})}catch{}}}
else if(kind==='account'){o.id=id;o.opening=Number(o.opening)||0;o.createdAt=existing?.createdAt||new Date().toISOString();await put('accounts',o)}else if(kind==='member'){o.id=id;await put('members',o)}else if(kind==='budget'){o.id=id;o.amount=Number(o.amount);o.month=currentMonth();await put('budgets',o)}else if(kind==='reminder'){o.id=id;o.amount=Number(o.amount)||0;await put('reminders',o)}else if(kind==='category'){o.id=id;await put('categories',o)}closeModal();toast(tr('saved'));await renderAll();}
async function removeRecord(storeName,id){if(!confirm(tr('confirmDelete')))return;await del(storeName,id);if(storeName==='transactions')await del('farm',id).catch(()=>{});toast(tr('deleted'));renderAll()}
function recordIcon(r){return categoryIcon[baseCategories.find(k=>tr(k)===r.category)]||({income:'↙',expense:'↗',transfer:'⇄','loan-given':'↗','loan-taken':'↙',repayment:'↔'}[r.type]||'•')}
function recordTitle(r){return r.title||r.category||typeLabel(r.type)}function recordMeta(r){let a=(window.accounts||[]).find(x=>x.id===r.account);let m=(window.members||[]).find(x=>x.id===r.member);return [r.date,typeLabel(r.type),a?.name,m?.name,r.person].filter(Boolean).join(' · ')}function amountClass(r){return r.type==='income'||r.type==='loan-taken'?'positive':r.type==='expense'||r.type==='loan-given'?'negative':''}function amountText(r){let prefix=['income','loan-taken'].includes(r.type)?'+':['expense','loan-given'].includes(r.type)?'−':'';return prefix+fmt(r.amount,r.currency||'INR')}
function recordHTML(r,storeName='transactions'){return `<div class="record"><div class="record-icon">${recordIcon(r)}</div><div class="record-main"><b>${escapeHtml(recordTitle(r))}</b><small>${escapeHtml(recordMeta(r))}</small></div><div><div class="record-amount ${amountClass(r)}">${escapeHtml(amountText(r))}</div><div class="record-actions"><button class="mini-btn" data-edit="${r.id}" data-store="${storeName}">${tr('edit')}</button><button class="mini-btn" data-delete="${r.id}" data-store="${storeName}">×</button></div></div></div>`}
function emptyHTML(text){return `<div class="empty">${escapeHtml(text)}</div>`}
function monthOf(d){return String(d||'').slice(0,7)}function sum(list,fn=()=>true){return list.filter(fn).reduce((n,x)=>n+Number(x.amount||0),0)}function accountBalance(a,txs){let b=Number(a.opening)||0;txs.forEach(t=>{if(t.currency!==(a.currency||'INR'))return;if(t.type==='transfer'){if(t.fromAccount===a.id)b-=Number(t.amount);if(t.toAccount===a.id)b+=Number(t.amount)}else if(t.account===a.id){if(['income','loan-taken'].includes(t.type))b+=Number(t.amount);else if(['expense','loan-given','repayment'].includes(t.type))b-=Number(t.amount)}});return b}
async function renderAll(){if(!db)return;window.accounts=await all('accounts');window.transactions=await all('transactions');window.members=await all('members');window.budgets=await all('budgets');window.reminders=await all('reminders');window.customCategories=await all('categories');window.farm=await all('farm');renderDashboard();renderTransactions();renderAccounts();renderFarm();renderMembers();renderReports();renderGrocery();renderOrders();renderBackupReminder();renderRechargeReminders()}
function renderDashboard(){const txs=window.transactions||[],month=currentMonth(),inc=sum(txs,t=>monthOf(t.date)===month&&t.type==='income'),exp=sum(txs,t=>monthOf(t.date)===month&&t.type==='expense');const balances=(window.accounts||[]).map(a=>({a,b:accountBalance(a,txs)}));const totalINR=balances.filter(x=>x.a.currency==='INR').reduce((n,x)=>n+x.b,0);$('#totalBalance').textContent=fmt(totalINR,'INR')+(balances.some(x=>x.a.currency!=='INR')?' + foreign balances':'');$('#monthIncome').textContent=fmt(inc);$('#monthExpense').textContent=fmt(exp);$('#statIncome').textContent=fmt(inc);$('#statExpense').textContent=fmt(exp);$('#statAccounts').textContent=(window.accounts||[]).length;$('#statReminders').textContent=(window.reminders||[]).filter(r=>r.status!=='paid'&&r.dueDate>=today()).length;const recent=[...txs].sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||'').localeCompare(a.createdAt||'')).slice(0,5);$('#recentList').innerHTML=recent.length?recent.map(r=>recordHTML(r)).join(''):emptyHTML(tr('noRecords'))}
function renderTransactions(){let list=[...(window.transactions||[])].sort((a,b)=>(b.date||'').localeCompare(a.date||''));const q=($('#searchTransactions')?.value||'').toLowerCase(),type=$('#filterType')?.value||'all';if(q)list=list.filter(r=>[r.title,r.category,r.person,r.notes,r.date].join(' ').toLowerCase().includes(q));if(type!=='all')list=list.filter(r=>r.type===type);$('#transactionList').innerHTML=list.length?list.map(r=>recordHTML(r)).join(''):emptyHTML(tr('noRecords'))}
function renderAccounts(){const accounts=window.accounts||[],txs=window.transactions||[];$('#accountList').innerHTML=accounts.length?accounts.map(a=>`<article class="account-card"><div class="account-symbol">${({cash:'💵',bank:'🏦',upi:'📱',card:'💳',wallet:'👛',other:'▣'}[a.type]||'▣')}</div><div class="account-info"><b>${escapeHtml(a.name)}</b><small>${escapeHtml(tr(a.type)||a.type)} · ${a.currency}</small><div class="record-actions"><button class="mini-btn" data-edit="${a.id}" data-store="accounts">${tr('edit')}</button><button class="mini-btn" data-delete="${a.id}" data-store="accounts">×</button></div></div><div class="account-balance">${fmt(accountBalance(a,txs),a.currency)}</div></article>`).join(''):emptyHTML(tr('noAccounts'))}
function renderFarm(){const txs=(window.transactions||[]).filter(t=>t.farm||t.category===tr('farmingCategory')||t.category===tr('farmIncomeCat')||t.category===tr('milkIncome'));$('#farmCosts').textContent=fmt(sum(txs,t=>t.type==='expense'));$('#farmIncome').textContent=fmt(sum(txs,t=>t.type==='income'));const list=[...txs].sort((a,b)=>(b.date||'').localeCompare(a.date||''));$('#farmList').innerHTML=list.length?list.map(r=>recordHTML(r)).join(''):emptyHTML(tr('noRecords'))}
function renderMembers(){const ms=window.members||[];$('#memberList').innerHTML=ms.length?ms.map(m=>`<div class="record"><div class="record-icon">♙</div><div class="record-main"><b>${escapeHtml(m.name)}</b><small>${escapeHtml(m.phone||'')}</small></div><div class="record-actions"><button class="mini-btn" data-edit="${m.id}" data-store="members">${tr('edit')}</button><button class="mini-btn" data-delete="${m.id}" data-store="members">×</button></div></div>`).join(''):emptyHTML(tr('noMembers'));const cs=window.customCategories||[];$('#customCategoryList').innerHTML=cs.length?cs.map(c=>`<div class="record"><div class="record-icon">◈</div><div class="record-main"><b>${escapeHtml(c.name)}</b></div><button class="mini-btn" data-delete="${c.id}" data-store="categories">×</button></div>`).join(''):emptyHTML(tr('noCategories'))}
function renderReports(){if(!$('#reportMonth'))return;const month=$('#reportMonth').value||currentMonth();if(!$('#reportMonth').value)$('#reportMonth').value=month;const txs=(window.transactions||[]).filter(t=>monthOf(t.date)===month),inc=sum(txs,t=>t.type==='income'),exp=sum(txs,t=>t.type==='expense');$('#reportIncome').textContent=fmt(inc);$('#reportExpense').textContent=fmt(exp);$('#reportNet').textContent=fmt(inc-exp);const cats={};txs.filter(t=>t.type==='expense').forEach(t=>cats[t.category||tr('other')]=(cats[t.category||tr('other')]||0)+Number(t.amount||0));const sorted=Object.entries(cats).sort((a,b)=>b[1]-a[1]);const max=sorted[0]?.[1]||1;$('#categoryReport').innerHTML=sorted.length?sorted.map(([name,val])=>`<div class="bar-row"><div class="bar-label"><span>${escapeHtml(name)}</span><b>${fmt(val)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,val/max*100)}%"></div></div></div>`).join(''):emptyHTML(tr('noData'));const budgets=(window.budgets||[]);$('#budgetList').innerHTML=budgets.length?budgets.map(b=>{const spent=sum(txs,t=>t.type==='expense'&&t.category===b.category);const pct=b.amount?Math.min(100,spent/b.amount*100):0;return `<div class="bar-row"><div class="bar-label"><span>${escapeHtml(b.category)}</span><b>${fmt(spent)} / ${fmt(b.amount)}</b></div><div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${spent>b.amount?'#c15b49':'var(--green2)'}"></div></div><div class="record-actions"><button class="mini-btn" data-edit="${b.id}" data-store="budgets">${tr('edit')}</button><button class="mini-btn" data-delete="${b.id}" data-store="budgets">×</button></div>${spent>b.amount?`<small class="negative">${tr('budgetOver')}</small>`:''}</div>`}).join(''):emptyHTML(tr('noBudgets'));const rems=[...(window.reminders||[])].sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||''));$('#reminderList').innerHTML=rems.length?rems.map(r=>`<div class="record"><div class="record-icon">◷</div><div class="record-main"><b>${escapeHtml(r.title)}</b><small>${escapeHtml(r.dueDate)} · ${escapeHtml(tr(r.frequency)||r.frequency)} · ${escapeHtml(tr(r.status)||r.status)}</small>${r.amount?`<small>${fmt(r.amount)}</small>`:''}</div><div class="record-actions"><button class="mini-btn" data-edit="${r.id}" data-store="reminders">${tr('edit')}</button><button class="mini-btn" data-delete="${r.id}" data-store="reminders">×</button></div></div>`).join(''):emptyHTML(tr('noReminders'))}

function renderRechargeReminders(){const todayStr=today();const due=(window.reminders||[]).filter(r=>r.kind==='mobileRecharge'&&r.status!=='paid'&&r.dueDate<=todayStr);if(due.length&&!sessionStorage.getItem('ghk_recharge_notice_'+todayStr)){setTimeout(()=>toast((state.lang==='hi'?'मोबाइल रिचार्ज रिमाइंडर: ':'Mobile recharge reminder: ')+due.map(r=>r.title.replace(/^.*?: /,'')).slice(0,2).join(', ')),1100);sessionStorage.setItem('ghk_recharge_notice_'+todayStr,'1');if('Notification'in window&&Notification.permission==='granted'){due.forEach(r=>{try{new Notification('GharKhata',{body:r.title+' · '+r.dueDate})}catch{}})}}}
function renderBackupReminder(){const toggle=$('#backupReminderToggle');if(toggle)toggle.checked=state.backupReminder;if(!state.backupReminder)return;let show=!state.lastBackup;if(state.lastBackup){const days=(Date.now()-new Date(state.lastBackup).getTime())/86400000;show=days>7}if(show){const key=state.lastBackup?'backupNeeded':'backupNever';if(!sessionStorage.getItem('hem_backup_notice')){setTimeout(()=>toast(tr(key)),700);sessionStorage.setItem('hem_backup_notice','1')}}}
async function editFromStore(name,id){const items=await all(name),r=items.find(x=>x.id===id);if(!r)return;const kind=({transactions:r.farm?'farmTransaction':'transaction',accounts:'account',members:'member',budgets:'budget',reminders:'reminder',categories:'category'})[name];openModal(kind,r,kind==='transaction'?{type:r.type}:null)}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}async function backup(){const data={app:'HouseholdExpenseManager',version:1,exportedAt:new Date().toISOString(),data:{}};for(const s of ['transactions','accounts','members','budgets','reminders','categories','farm','groceryLists','orders'])data.data[s]=await all(s);data.settings={lang:state.lang,backupReminder:state.backupReminder};download(`household-backup-${today()}.json`,JSON.stringify(data,null,2),'application/json');state.lastBackup=new Date().toISOString();localStorage.setItem('hem_last_backup',state.lastBackup);toast(tr('backupDone'))}
async function restore(file){try{const obj=JSON.parse(await file.text());if(obj.app!=='HouseholdExpenseManager'||!obj.data)throw new Error('bad');if(!confirm(tr('restoreConfirm')))return;for(const s of ['transactions','accounts','members','budgets','reminders','categories','farm','groceryLists','orders']){await clearStore(s);for(const row of (obj.data[s]||[]))await put(s,row)}if(obj.settings?.lang)setLang(obj.settings.lang);await renderAll();toast(tr('restoreDone'))}catch(e){toast(tr('restoreFailed'))}}
async function exportCsv(){
 const txs=window.transactions||[];
 const headers=['date','type','amount','currency','category','subcategory','account','fromAccount','toAccount','member','person','method','title','reason','notes','orderId','crop','workType'];
 const quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 const rows=txs.map(t=>headers.map(h=>{
  let value=t[h];
  if(h==='account') value=(window.accounts||[]).find(a=>a.id===t.account)?.name||t.account||'';
  if(h==='fromAccount') value=(window.accounts||[]).find(a=>a.id===t.fromAccount)?.name||t.fromAccount||'';
  if(h==='toAccount') value=(window.accounts||[]).find(a=>a.id===t.toAccount)?.name||t.toAccount||'';
  if(h==='member') value=(window.members||[]).find(m=>m.id===t.member)?.name||'';
  return quote(value);
 }).join(','));
 const csv=[headers.join(','),...rows].join('\r\n');
 download(`household-transactions-${today()}.csv`,'\ufeff'+csv,'text/csv;charset=utf-8');
}

