function subcategoryOptions(category){const found=Object.entries(subcategoryMap).find(([k])=>tr(k)===category||k===category);let arr=found?.[1]||['सामान्य खर्च','मरम्मत','अन्य'];if(!found&&state.lang==='en'){arr=['General expense','Repairs','Other'];return [{value:'',label:'Choose (optional)'},...arr.map(x=>({value:x,label:x}))]}return [{value:'',label:state.lang==='en'?'Choose (optional)':'चुनें (वैकल्पिक)'},...arr.map(x=>({value:x,label:state.lang==='en'?(subcategoryEnglish[x]||x):x}))]}
const APP_URL='https://fabrication4man-bot.github.io/GharKhata/';
function groceryDefaultRows(){return Array.from({length:50},(_,i)=>({no:i+1,item:'',qty:'',unit:'PCS',price:''}))}
function groceryMonth(){return $('#groceryMonth')?.value||currentMonth()}
function translateGrocery(){const hi=state.lang==='hi';const t={title:hi?'मासिक किराना सूची':'Monthly Grocery List',desc:hi?'50 लाइन · यूनिट चुनें · कीमत वैकल्पिक':'50 rows · Choose unit · Price optional',month:hi?'महीना':'Month',load:hi?'लिस्ट खोलें':'Load list',save:hi?'लिस्ट सेव करें':'Save list',add:hi?'+ नई पंक्ति जोड़ें':'+ Add row',serial:hi?'क्र.':'No.',item:hi?'सामान का नाम':'Item name',qty:hi?'मात्रा':'Quantity',unit:hi?'यूनिट':'Unit',price:hi?'कीमत (वैकल्पिक)':'Price (optional)',download:hi?'PDF डाउनलोड / प्रिंट':'Download PDF / Print',csv:hi?'CSV डाउनलोड':'Download CSV',share:hi?'लिस्ट शेयर करें':'Share list',hint:hi?'PDF बनाने के लिए प्रिंट स्क्रीन में “Save as PDF” चुनें।':'To create a PDF, choose “Save as PDF” in the print dialog.'};const root=$('#grocery');if(!root)return;const h=root.querySelector('h2');if(h)h.textContent=t.title;const desc=root.querySelector('.page-title .muted');if(desc)desc.textContent=t.desc;const labels=root.querySelectorAll('.grocery-controls label');if(labels[0])labels[0].childNodes[0].textContent=t.month;$('#loadGrocery').textContent=t.load;$('#saveGrocery').textContent=t.save;const heads=root.querySelectorAll('.grocery-table th');[t.serial,t.item,t.qty,t.unit,t.price].forEach((v,i)=>{if(heads[i])heads[i].textContent=v});$('#addGroceryRow').textContent=t.add;$('#downloadGrocery').textContent=t.csv;$('#printGrocery').textContent=t.download;$('#shareGrocery').textContent=t.share;$('#groceryPdfHint').textContent=t.hint;const navG=$('.nav-item[data-page=\"grocery\"] small');if(navG)navG.textContent=hi?'किराना':'Groceries';const navO=$('.nav-item[data-page=\"orders\"] small');if(navO)navO.textContent=hi?'ऑर्डर':'Orders';const navS=$('.nav-item[data-page=\"shareapp\"] small');if(navS)navS.textContent=hi?'शेयर':'Share'}
function renderGrocery(){const monthEl=$('#groceryMonth');if(!monthEl)return;if(!monthEl.value)monthEl.value=currentMonth();let rows=window.groceryRows||groceryDefaultRows();const units=state.lang==='hi'?[['Gram','ग्राम'],['Kilogram','किलोग्राम'],['Liter','लीटर'],['Milliliter','मिलीलीटर'],['PCS','पीस'],['रुपये के हिसाब से','रुपये के हिसाब से']]:[['Gram','Gram'],['Kilogram','Kilogram'],['Liter','Liter'],['Milliliter','Milliliter'],['PCS','PCS'],['रुपये के हिसाब से','By amount']];$('#groceryRows').innerHTML=rows.map((r,i)=>`<tr><td>${i+1}</td><td><input data-grocery="item" data-i="${i}" value="${escapeHtml(r.item||'')}" aria-label="${state.lang==='hi'?'सामान':'Item'} ${i+1}" placeholder="${state.lang==='hi'?'सामान का नाम':'Item name'}"></td><td><input data-grocery="qty" data-i="${i}" type="number" min="0" step="any" value="${escapeHtml(r.qty||'')}" aria-label="${state.lang==='hi'?'मात्रा':'Quantity'}"></td><td><select data-grocery="unit" data-i="${i}">${units.map(([v,label])=>`<option value="${escapeHtml(v)}" ${v===(r.unit||'PCS')?'selected':''}>${label}</option>`).join('')}</select></td><td><input data-grocery="price" data-i="${i}" type="number" min="0" step="0.01" value="${escapeHtml(r.price||'')}" placeholder="${state.lang==='hi'?'वैकल्पिक':'Optional'}" aria-label="${state.lang==='hi'?'कीमत':'Price'}"></td></tr>`).join('');translateGrocery()}
function readGroceryRows(){return [...document.querySelectorAll('#groceryRows tr')].map((tr,i)=>({no:i+1,item:tr.querySelector('[data-grocery=item]').value.trim(),qty:tr.querySelector('[data-grocery=qty]').value,unit:tr.querySelector('[data-grocery=unit]').value,price:tr.querySelector('[data-grocery=price]').value}));}
async function saveGrocery(silent=false){const month=groceryMonth(),rows=readGroceryRows();await put('groceryLists',{id:month,month,rows,updatedAt:new Date().toISOString()});window.groceryRows=rows;if(!silent)toast(state.lang==='hi'?'मासिक किराना सूची सेव हो गई':'Monthly grocery list saved');}
async function loadGrocery(silent=false){const month=groceryMonth(),saved=(await all('groceryLists')).find(x=>x.month===month);window.groceryRows=saved?.rows||groceryDefaultRows();renderGrocery();if(!silent)toast(saved?'सेव की गई लिस्ट खुल गई':'नई मासिक लिस्ट तैयार है')}
function printGroceryPdf(){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const hi=state.lang==='hi';const title=hi?'मासिक किराना सूची':'Monthly Grocery List';const unitLabels=hi?{'Gram':'ग्राम','Kilogram':'किलोग्राम','Liter':'लीटर','Milliliter':'मिलीलीटर','PCS':'पीस','रुपये के हिसाब से':'रुपये के हिसाब से'}:{};const body=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${escapeHtml(r.item)}</td><td>${escapeHtml(r.qty)}</td><td>${escapeHtml(unitLabels[r.unit]||r.unit)}</td><td>${escapeHtml(r.price)}</td></tr>`).join('');const w=window.open('','_blank');if(!w){toast(hi?'पॉप-अप की अनुमति दें':'Allow pop-ups to create PDF');return}w.document.write(`<!doctype html><html lang="${hi?'hi':'en'}"><head><meta charset="utf-8"><title>GharKhata - ${title}</title><style>body{font-family:Arial,'Noto Sans Devanagari',sans-serif;color:#17231f;padding:20px}h1{color:#155e4b;margin-bottom:4px}.meta{color:#64746c;margin-bottom:16px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #cbd8d0;padding:8px;text-align:left;overflow-wrap:anywhere}th{background:#edf5f0;color:#155e4b}.footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #ddd;margin-top:24px;padding-top:12px;font-size:12px}.footer img{width:100px;height:100px;object-fit:contain}@page{size:A4;margin:14mm}@media print{body{padding:0}}</style></head><body><h1>GharKhata</h1><div class="meta">${title} · ${escapeHtml(groceryMonth())}</div><table><thead><tr><th>${hi?'क्र.':'No.'}</th><th>${hi?'सामान का नाम':'Item name'}</th><th>${hi?'मात्रा':'Quantity'}</th><th>${hi?'यूनिट':'Unit'}</th><th>${hi?'कीमत':'Price'}</th></tr></thead><tbody>${body||`<tr><td colspan="5">${hi?'कोई सामान दर्ज नहीं है':'No items entered'}</td></tr>`}</tbody></table><div class="footer"><div><strong>GharKhata</strong><br>${hi?'घर का हर खर्च, एक जगह':'Every household expense, in one place'}<br>${hi?'ऐप खोलने के लिए QR स्कैन करें':'Scan QR to open the app'}</div><img src="${APP_URL}app-qr.png" alt="GharKhata app QR code"></div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}
function groceryCsv(){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const hi=state.lang==='hi';const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const headers=hi?['क्रमांक','सामान का नाम','मात्रा','यूनिट','कीमत']:['No.','Item name','Quantity','Unit','Price'];const unit=hi?{'Gram':'ग्राम','Kilogram':'किलोग्राम','Liter':'लीटर','Milliliter':'मिलीलीटर','PCS':'पीस','रुपये के हिसाब से':'रुपये के हिसाब से'}:{};return [headers.map(q).join(','),...rows.map(r=>[r.no,r.item,r.qty,unit[r.unit]||r.unit,r.price].map(q).join(','))].join('\r\n')}
async function shareText(title,textValue){if(navigator.share){try{await navigator.share({title,text:textValue,url:APP_URL});return}catch(e){if(e.name==='AbortError')return}}download((title||'gharkhata')+'.txt',textValue,'text/plain;charset=utf-8')}
async function shareGrocery(){const rows=readGroceryRows().filter(r=>r.item||r.qty||r.price);const textValue='GharKhata मासिक किराना सूची — '+groceryMonth()+'\n'+rows.map(r=>`${r.no}. ${r.item||'—'} | ${r.qty||'—'} ${r.unit} | ${r.price?'कीमत: '+r.price:'कीमत खाली'}`).join('\n');await shareText('GharKhata-Kirana-'+groceryMonth(),textValue)}
function printCurrent(id,title){const el=$(id);if(!el)return;const w=window.open('','_blank');if(!w){toast('ब्राउज़र में pop-up अनुमति दें');return}w.document.write('<html><head><title>'+escapeHtml(title)+'</title><style>body{font-family:Arial,sans-serif;padding:20px;color:#17231f}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;text-align:left}button,input,select{display:none}@media print{body{padding:0}}</style></head><body><h1>'+escapeHtml(title)+'</h1>'+el.innerHTML+'</body></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}
async function downloadReport(){const month=$('#reportMonth').value||currentMonth();const txs=(window.transactions||[]).filter(t=>monthOf(t.date)===month);const inc=sum(txs,t=>t.type==='income'),exp=sum(txs,t=>t.type==='expense');const txt=`GharKhata — मासिक रिपोर्ट\nमहीना: ${month}\nकुल आय: ${fmt(inc)}\nकुल खर्च: ${fmt(exp)}\nबचत / अंतर: ${fmt(inc-exp)}\n\nखर्च का विवरण:\n`+txs.filter(t=>t.type==='expense').map(t=>`${t.date} | ${t.category} | ${t.subcategory||''} | ${t.title||''} | ${fmt(t.amount,t.currency||'INR')}`).join('\n');download(`GharKhata-report-${month}.txt`,txt,'text/plain;charset=utf-8')}
async function shareReport(){const month=$('#reportMonth').value||currentMonth();const txs=(window.transactions||[]).filter(t=>monthOf(t.date)===month);const inc=sum(txs,t=>t.type==='income'),exp=sum(txs,t=>t.type==='expense');await shareText('GharKhata मासिक रिपोर्ट',`महीना: ${month}\nकुल आय: ${fmt(inc)}\nकुल खर्च: ${fmt(exp)}\nबचत / अंतर: ${fmt(inc-exp)}\nरिपोर्ट ऐप में उपलब्ध है।`)}
async function renderOrders(){if(!$('#orderList'))return;const rows=(await all('orders')).sort((a,b)=>(b.orderDate||'').localeCompare(a.orderDate||''));$('#orderList').innerHTML=rows.length?rows.map(o=>`<div class="record"><div class="record-icon">📦</div><div class="record-main"><b>${escapeHtml(o.item)} — ${escapeHtml(o.platform)}</b><small>${escapeHtml(o.orderDate||'')} · ${escapeHtml(o.status||'')} · ID: ${escapeHtml(o.orderId||'—')}<br>मात्रा: ${escapeHtml(o.quantity||1)} · सामान ₹${Number(o.price||0).toFixed(2)} + डिलीवरी ₹${Number(o.shipping||0).toFixed(2)} − डिस्काउंट ₹${Number(o.discount||0).toFixed(2)} · रिफंड ₹${Number(o.refund||0).toFixed(2)}</small><div class="record-actions"><button class="mini-btn" data-order-delete="${o.id}">हटाएँ</button></div></div><div class="record-amount">₹${(Number(o.price||0)+Number(o.shipping||0)-Number(o.discount||0)-Number(o.refund||0)).toFixed(2)}</div></div>`).join(''):emptyHTML('अभी कोई ऑनलाइन ऑर्डर दर्ज नहीं है।')}
async function saveOrder(e){e.preventDefault();const f=new FormData(e.target),o=Object.fromEntries(f.entries());o.id=uid();['quantity','price','shipping','discount','refund'].forEach(k=>o[k]=Number(o[k])||0);o.total=Math.max(0,o.price+o.shipping-o.discount);o.createdAt=new Date().toISOString();if(o.status!=='कैंसिल'&&o.total>0){const account=(window.accounts||[])[0];if(account){const net=Math.max(0,o.total-o.refund);const tx={id:uid(),date:o.orderDate||today(),amount:net,currency:account.currency||'INR',type:'expense',category:tr('ecommerce'),subcategory:o.category||'ऑनलाइन खरीदारी',account:account.id,member:'',method:o.payment||'',person:o.platform||'',title:o.item,notes:`Order ID: ${o.orderId||'—'}; status: ${o.status}; invoice: ${o.invoice||''}; ${o.notes||''}`,reason:o.notes||'',orderId:o.orderId||'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),ecommerce:true};await put('transactions',tx);o.transactionId=tx.id;}}await put('orders',o);e.target.reset();e.target.elements.orderDate.value=today();await renderAll();toast('ऑर्डर का विवरण सेव हो गया और खर्च रिपोर्ट में जोड़ा गया')}
async function exportOrders(){const rows=await all('orders'),heads=['platform','orderId','item','category','quantity','price','shipping','discount','total','orderDate','deliveryDate','payment','status','refund','invoice','notes'];const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('GharKhata-ecommerce-orders.csv','\ufeff'+[heads.join(','),...rows.map(o=>heads.map(k=>q(o[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')}
async function shareApp(){await shareText('GharKhata — घर का हर खर्च, एक जगह','GharKhata ऐप खोलें: '+APP_URL+'\nपरिवार के खर्च, किराना सूची, ऑनलाइन ऑर्डर और महीने की बचत का हिसाब एक जगह।')}
function initSharePage(){const of=$('#orderForm');if(of&&!of.elements.orderDate.value)of.elements.orderDate.value=today()}


