function addListeners(){document.addEventListener('click',async e=>{const pg=e.target.closest('[data-page]');if(pg){go(pg.dataset.page);return}const close=e.target.closest('[data-close-modal]');if(close){closeModal();return}const quick=e.target.closest('[data-type]');if(quick){openModal('transaction',null,{type:quick.dataset.type});return}const edit=e.target.closest('[data-edit]');if(edit){await editFromStore(edit.dataset.store,edit.dataset.edit);return}const delBtn=e.target.closest('[data-delete]');if(delBtn){await removeRecord(delBtn.dataset.store,delBtn.dataset.delete);return}const od=e.target.closest('[data-order-delete]');if(od){if(confirm('इस ऑर्डर को हटाएँ?')){const order=(await all('orders')).find(x=>x.id===od.dataset.orderDelete);await del('orders',od.dataset.orderDelete);if(order?.transactionId)await del('transactions',order.transactionId);await renderAll()}return}});$('#langToggle').onclick=()=>setLang(state.lang==='en'?'hi':'en');$('#settingsLang').onclick=()=>setLang(state.lang==='en'?'hi':'en');$('#quickAdd').onclick=()=>openModal('transaction');$('#newTransaction').onclick=()=>openModal('transaction');$('#newFarm').onclick=()=>openModal('farmTransaction',null,{type:'expense'});$('#newAccount').onclick=()=>openModal('account');$('#newMember').onclick=()=>openModal('member');$('#newBudget').onclick=()=>openModal('budget');$('#newReminder').onclick=()=>openModal('reminder');$('#newCategory').onclick=()=>openModal('category');$('#searchTransactions').oninput=renderTransactions;$('#filterType').onchange=renderTransactions;$('#reportMonth').onchange=renderReports;$('#exportCsv').onclick=exportCsv;$('#downloadReport').onclick=downloadReport;$('#printReport').onclick=()=>printCurrent('#reports','GharKhata मासिक रिपोर्ट');$('#shareReport').onclick=shareReport;$('#groceryMonth').onchange=()=>loadGrocery(true);$('#loadGrocery').onclick=()=>loadGrocery(false);$('#saveGrocery').onclick=saveGrocery;$('#downloadGrocery').onclick=()=>download('GharKhata-kirana-'+groceryMonth()+'.csv','\ufeff'+groceryCsv(),'text/csv;charset=utf-8');$('#printGrocery').onclick=printGroceryPdf;$('#addGroceryRow').onclick=async()=>{const rows=readGroceryRows();rows.push({no:rows.length+1,item:'',qty:'',unit:'PCS',price:''});window.groceryRows=rows;renderGrocery();await saveGrocery(true);};let grocerySaveTimer;$('#groceryRows').addEventListener('input',e=>{if(e.target.matches('[data-grocery]')){const rows=readGroceryRows();window.groceryRows=rows;clearTimeout(grocerySaveTimer);grocerySaveTimer=setTimeout(()=>saveGrocery(true),500)}});$('#groceryRows').addEventListener('change',e=>{if(e.target.matches('[data-grocery]'))saveGrocery(true)});$('#shareGrocery').onclick=shareGrocery;$('#orderForm').onsubmit=saveOrder;$('#exportOrders').onclick=exportOrders;$('#shareAppLink').onclick=shareApp;$('#copyAppLink').onclick=async()=>{try{await navigator.clipboard.writeText(APP_URL);toast('ऐप लिंक कॉपी हो गया')}catch{await shareApp()}};$('#createBackup').onclick=backup;$('#restoreFile').onchange=e=>{if(e.target.files[0])restore(e.target.files[0]);e.target.value=''};$('#backupReminderToggle').onchange=e=>{state.backupReminder=e.target.checked;localStorage.setItem('hem_backup_reminder',String(state.backupReminder));toast(tr('saved'))};$('#clearData').onclick=async()=>{if(!confirm(tr('confirmClear')))return;for(const s of ['transactions','accounts','members','budgets','reminders','categories','farm','groceryLists','orders'])await clearStore(s);await seed();await renderAll();toast(tr('deleted'))};$$('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));initSharePage();if($('#orderForm'))$('#orderForm').elements.orderDate.value=today();}
async function init(){try{db=await openDB();await seed();window.groceryRows=groceryDefaultRows();addListeners();setLang(state.lang);await loadGrocery(true);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!window.isSecureContext&&location.protocol!=='file:')toast('For offline install, open this app over HTTPS.')}catch(e){document.body.innerHTML='<main><h2>Storage unavailable</h2><p>This browser could not open local storage. Try opening the app in Chrome.</p></main>';console.error(e)}}
init();
